"""Destination profiles and collection preview text in supported languages."""

_LANGUAGES = ("es", "fr", "de", "it", "pt-BR", "bg", "nl", "pl", "ja", "ko", "zh-Hans")
PREPARATION_PREVIEW_TRANSLATIONS = {}


def _add(source, translations):
    values = translations.split("|")
    if len(values) != len(_LANGUAGES):
        raise ValueError(f"Incomplete preparation translation: {source}")
    PREPARATION_PREVIEW_TRANSLATIONS[source] = dict(zip(_LANGUAGES, values))


